// 嵌入来源追踪：确保缓存安全性

// 核心思想：用 provider+endpoint+model+dimension 构建确定性指纹
// 切换模型后指纹变化 → 旧缓存自动失效 → 防止不同维度向量混用

function build_provenance(provider, endpoint, model, dimension):
    payload = {
        "provider":  normalize(provider),          // 去空格、转小写
        "endpoint":  normalize_endpoint(endpoint), // 去掉 query/fragment/apikey
        "model":     strip(model),
        "dimension": max(0, int(dimension)),
    }
    return json.dumps(payload, sort_keys=True)  // 确定性序列化

function normalize_endpoint(url):
    // 故意丢弃 query string 和 fragment（可能含 API 密钥）
    // 移除 userinfo（用户名密码）
    return scheme + host + path   // 只保留稳定部分

// ★ 两阶段 RAG 核心：Recall → LLM Precision

RECALL_THRESHOLD = 0.55    // 故意低阈值 → 最大化召回率
STANDALONE_THRESHOLD = 0.78 // 无 LLM 时的保守策略

// Stage 2a: 嵌入召回——低阈值广撒网
function embedding_recall(candidates, disliked_topics):
    topic_vectors = [embed(topic) for topic in disliked_topics]

    results = []
    for cand in candidates:
        cand_vec = embed(cand.title + cand.topic)  // 候选文本 = 标题+话题
        for topic, topic_vec in topic_vectors:
            sim = cosine_similarity(cand_vec, topic_vec)
            if sim >= 0.55:           // 低阈值：宁可错杀，不可放过
                results.append((cand, sim, topic))
                break                 // 只需最佳匹配
    return results

// Stage 2b: LLM 精判——对召回集逐条 keep/purge
// → 由 LLM 做最终判断，弥补低阈值带来的误报

// ★ 画像去重核心参数与反泛化守卫

// 反泛化黑名单：禁止合并为过于宽泛的"伞形词"
BANNED_CANONICALS = frozenset({
    "低质", "营销", "标题党", "广告", "无聊", "套路",
    "水分", "游戏", "视频", "内容",
})

// 五阶段流水线的关键阈值
SIMILARITY_THRESHOLD = 0.85     // 聚类阈值：只合并"几乎相同"的标签
NO_MERGE_CAP       = 16000      // 跳过记忆上限
JUDGE_BATCH_SIZE   = 32         // 每次 LLM 调用处理 32 个聚类
MIN_INTERVAL       = 12 * 3600  // 最小运行间隔 12 小时

// 流水线伪代码：
// 1. 规则层合并（同分类+同名 → 直接合并，零 LLM 调用）
// 2. 嵌入聚类（cosine > 0.85 → 归为一簇）
// 3. 跳过记忆（已判断"不同"的标签对 → 跳过）
// 4. LLM 批量判断（32 簇/次 → merge or keep）
// 5. 验证并执行合并

